// Lifecycle authorizations v1 (Prompt 17C, D-135, D-136): the Dart
// derivations must produce exactly the challenges the server derives and
// verifies. Vector generated by functions/test/vectors/generate.mjs.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:sirf_hum/security/messaging/lifecycle_authorization.dart';

Uint8List _hex(String s) => Uint8List.fromList([
  for (var i = 0; i < s.length; i += 2)
    int.parse(s.substring(i, i + 2), radix: 16),
]);

String _toHex(List<int> b) =>
    b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();

void main() {
  final v =
      jsonDecode(
            File(
              'functions/test/vectors/lifecycle_authorization_v1.json',
            ).readAsStringSync(),
          )
          as Map<String, Object?>;
  final r = v['recovery']! as Map<String, Object?>;
  final u = v['unpair']! as Map<String, Object?>;

  Uint8List recovery({int? epoch, int? trustEpoch, String? account}) =>
      recoveryAuthorizationChallenge(
        nonce: _hex(v['nonceHex']! as String),
        accountId: account ?? v['accountId']! as String,
        deviceId: _hex(v['deviceIdHex']! as String),
        conversationId: _hex(r['conversationIdHex']! as String),
        epoch: epoch ?? r['epoch']! as int,
        trustEpoch: trustEpoch ?? r['trustEpoch']! as int,
      );

  Uint8List unpair({String? account, Uint8List? coupleId}) =>
      unpairAuthorizationChallenge(
        nonce: _hex(v['nonceHex']! as String),
        accountId: account ?? v['accountId']! as String,
        deviceId: _hex(v['deviceIdHex']! as String),
        coupleId: coupleId ?? _hex(u['coupleIdHex']! as String),
      );

  test('match the server-generated golden vectors (epoch above 2^32)', () {
    expect(_toHex(recovery()), r['challengeHex']);
    expect(_toHex(unpair()), u['challengeHex']);
  });

  test('epochs, trust epoch, account and couple are bound', () {
    final epoch = r['epoch']! as int;
    expect(_toHex(recovery(epoch: epoch + 1)), isNot(r['challengeHex']));
    expect(_toHex(recovery(trustEpoch: 4)), isNot(r['challengeHex']));
    expect(_toHex(recovery(account: 'accountB')), isNot(r['challengeHex']));
    expect(_toHex(unpair(account: 'accountB')), isNot(u['challengeHex']));
    expect(_toHex(unpair(coupleId: Uint8List(16))), isNot(u['challengeHex']));
  });

  test('malformed fields are refused', () {
    expect(() => recovery(epoch: -1), throwsArgumentError);
    expect(() => unpair(coupleId: Uint8List(15)), throwsArgumentError);
  });
}
